      });
    }
  });
  return tasks;
}

/**
 * Buang task yang tidak perlu di-insert: deadline sudah lewat dan belum
 * pernah tercatat. (Task yang sudah ada tetap di-update lewat SQL.)
 * Task berstatus done tetap dikirim agar status di DB ikut ter-update.
 */
function filterRelevant(tasks, now) {
  return (tasks || []).filter((t) => {
    if (t.status === 'done') return true;
    if (!t.deadline) return true;
    return new Date(t.deadline).getTime() >= now.getTime();
  });
}
// ===== akhir library =====
// Satu item per kelas Classroom yang relevan. Kelas semester lalu (dibuat
// sebelum semester_start) dan kelas di classroom_ignore dilewati, jadi API
// tugasnya tidak dipanggil. Jika Classroom gagal / semua kelas dilewati,
// kirim satu placeholder agar alur tetap jalan.
const settings = $('S: Muat setting').first().json.settings || {};
const res = $input.first().json || {};
const courses = Array.isArray(res.courses) ? res.courses : [];
const { kept, ignored } = filterCourses(courses, {
  since: parseSemesterStart(settings.semester_start),
  ignore: parseIgnoreList(settings.classroom_ignore),
});
if (kept.length === 0) {
  return [{
    json: {
      id: '', name: '', ignored,
      classroom_error: res.error ? (res.error.message || String(res.error)) : null,
    },
  }];
}
return kept.map((c) => ({ json: { id: c.id, name: c.name, ignored, classroom_error: null } }));

// ===== library (dibangun dari src/lib — edit di sana, bukan di sini) =====
// ---------------------------------------------------------------------------
// lib/normalize.js — ubah data mentah Lentera & Classroom jadi "task" seragam:
// { source, source_id, course, title, task_type, deadline (ISO UTC|null),
//   effort_minutes, weight (1-3), status ('open'|'done') }
// Estimasi effort di sini hanya tebakan awal (heuristik). User bisa
// mengoreksinya lewat chat, dan agent menyimpannya ke database.
// ---------------------------------------------------------------------------

/** Tebak jenis, effort (menit), dan bobot dari judul tugas. */
function guessTaskMeta(title, hint) {
  const t = `${title || ''} ${hint || ''}`.toLowerCase();
  if (/\b(uts|uas|ujian|exam|midterm|final test)\b/.test(t)) return { task_type: 'ujian', effort_minutes: 360, weight: 3 };
  if (/knowledge check/.test(t)) return { task_type: 'kuis', effort_minutes: 30, weight: 1 };
  if (/\b(quiz|kuis)/.test(t)) return { task_type: 'kuis', effort_minutes: 45, weight: 2 };
  if (/\b(lab|praktikum)\b/.test(t)) return { task_type: 'lab', effort_minutes: 120, weight: 2 };
  if (/\b(project|proyek|laporan|report|makalah|paper)\b/.test(t)) return { task_type: 'tugas', effort_minutes: 240, weight: 3 };
  if (/\b(assessment|tugas|assignment|homework|pr)\b/.test(t)) return { task_type: 'tugas', effort_minutes: 120, weight: 2 };
  return { task_type: 'tugas', effort_minutes: 90, weight: 2 };
}

// Moodle membuat beberapa event untuk satu aktivitas, mis. "Quiz07 ... opens",
// "... closes", "... should be completed", "... is due". Kita gabungkan per
// aktivitas dan ambil deadline yang paling relevan.
const MOODLE_SUFFIXES = [
  { re: /\s+closes$/i, kind: 'close', rank: 1 },
  { re: /\s+is due$/i, kind: 'due', rank: 1 },
  { re: /\s+due$/i, kind: 'due', rank: 1 },
  { re: /\s+should be completed$/i, kind: 'complete', rank: 2 },
  { re: /\s+opens$/i, kind: 'open', rank: 9 },
];

function splitMoodleSummary(summary) {
  const s = String(summary || '').replace(/\s+/g, ' ').trim();
  for (const suf of MOODLE_SUFFIXES) {
    if (suf.re.test(s)) return { base: s.replace(suf.re, '').trim(), kind: suf.kind, rank: suf.rank };
  }
  return { base: s, kind: 'event', rank: 3 };
}

/**
 * Event Lentera -> task. Satu task per (kode matkul, nama aktivitas).
 * Event "opens" diabaikan. Deadline = event dengan rank terkecil (closes/due),
 * jika sama rank ambil yang paling akhir.
 */
function lenteraToTasks(events) {
  const groups = new Map();
  for (const ev of events || []) {
    if (!ev || !ev.summary || !ev.start) continue;
    const { base, kind, rank } = splitMoodleSummary(ev.summary);
    if (kind === 'open') continue;
    const course = (ev.categories || '').trim() || 'Lentera';
    const key = `${course}::${base}`;
    const prev = groups.get(key);
    if (!prev || rank < prev.rank || (rank === prev.rank && ev.start > prev.start)) {
      groups.set(key, { key, course, base, rank, start: ev.start, description: ev.description || '' });
    }
  }
  const tasks = [];
  for (const g of groups.values()) {
    const meta = guessTaskMeta(g.base, g.description);
    tasks.push({
      source: 'lentera',
      source_id: g.key,
      course: g.course,
      title: g.base,
      task_type: meta.task_type,
      deadline: g.start.toISOString(),
      effort_minutes: meta.effort_minutes,
      weight: meta.weight,
      status: 'open',
    });
  }
  return tasks;
}

/** dueDate {year,month,day} + dueTime {hours,minutes} (UTC) -> Date | null */
function classroomDue(work) {
  const d = work && work.dueDate;
  if (!d || !d.year) return null;
  const t = work.dueTime || {};
  // Classroom: jika dueTime kosong, deadline = akhir hari (23:59 UTC tidak tepat
  // untuk WIB, jadi pakai 23:59 lokal = 16:59 UTC).
  if (t.hours === undefined && t.minutes === undefined) {
    return new Date(Date.UTC(d.year, d.month - 1, d.day, 16, 59));
  }
  return new Date(Date.UTC(d.year, d.month - 1, d.day, t.hours || 0, t.minutes || 0));
}

const DONE_STATES = ['TURNED_IN', 'RETURNED'];

/**
 * Pisahkan kelas Classroom yang masih relevan dari kelas semester lalu yang
 * belum di-archive dosen.
 *  - since:  kelas yang DIBUAT sebelum tanggal ini dianggap kelas lama.
 *  - ignore: daftar kata kunci (nama kelas atau id) yang diabaikan user.
 */
function filterCourses(courses, { since = null, ignore = [] } = {}) {
  const keys = (ignore || []).map((k) => String(k).trim().toLowerCase()).filter(Boolean);
  const kept = [];
  const ignored = [];
  for (const c of courses || []) {
    if (!c || !c.id) continue;
    const name = String(c.name || '').toLowerCase();
    const byKeyword = keys.some((k) => name.includes(k) || String(c.id) === k);
    const created = c.creationTime ? new Date(c.creationTime) : null;
    const byDate = since && created && created < since;
    if (byKeyword || byDate) ignored.push({ id: c.id, name: c.name || c.id, reason: byKeyword ? 'diabaikan user' : 'kelas semester lalu' });
    else kept.push(c);
  }
  return { kept, ignored };
}

/** "Basis Data, jarkom" -> ['Basis Data', 'jarkom'] */
function parseIgnoreList(text) {
  return String(text || '').split(',').map((s) => s.trim()).filter(Boolean);
}

/** "2026-08-01" -> Date 00:00 WIB, atau null kalau kosong/tidak valid. */
function parseSemesterStart(text) {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(text || '').trim());
  return m ? new Date(Date.UTC(+m[1], +m[2] - 1, +m[3]) - 7 * 3600e3) : null;
}

/**
 * courses: [{id, name}], workByCourse: [{courseWork:[...]}] (sejajar dengan
 * courses), subsByCourse: [{studentSubmissions:[...]}] (sejajar).
 * opts.since: tugas TANPA deadline yang dibuat sebelum tanggal ini dilewati
 * (sisa semester lalu yang tidak akan pernah "lewat deadline").
 */
function classroomToTasks(courses, workByCourse, subsByCourse, opts = {}) {
  const tasks = [];
  (courses || []).forEach((course, i) => {
    if (!course || !course.id) return;
    const works = ((workByCourse || [])[i] || {}).courseWork || [];
    const subs = ((subsByCourse || [])[i] || {}).studentSubmissions || [];
    const stateByWork = new Map(subs.map((s) => [s.courseWorkId, s.state]));
    for (const w of works) {
      if (w.state && w.state !== 'PUBLISHED') continue;
      const due = classroomDue(w);
      if (!due && opts.since && w.creationTime && new Date(w.creationTime) < opts.since) continue;
      const meta = guessTaskMeta(w.title, w.workType);
      if (w.workType === 'MULTIPLE_CHOICE_QUESTION' || w.workType === 'SHORT_ANSWER_QUESTION') {
        meta.effort_minutes = Math.min(meta.effort_minutes, 30);
      }
      const subState = stateByWork.get(w.id);
      tasks.push({
        source: 'classroom',
        source_id: String(w.id),
        course: course.name || course.id,
        title: w.title || '(tanpa judul)',
        task_type: meta.task_type,
        deadline: due ? due.toISOString() : null,
        effort_minutes: meta.effort_minutes,
        weight: meta.weight,
        status: DONE_STATES.includes(subState) ? 'done' : 'open',
      });
    }
  });
  return tasks;
}

/**
 * Buang task yang tidak perlu di-insert: deadline sudah lewat dan belum
 * pernah tercatat. (Task yang sudah ada tetap di-update lewat SQL.)
 * Task berstatus done tetap dikirim agar status di DB ikut ter-update.
 */
function filterRelevant(tasks, now) {
  return (tasks || []).filter((t) => {
    if (t.status === 'done') return true;
    if (!t.deadline) return true;
    return new Date(t.deadline).getTime() >= now.getTime();
  });
}
// ===== akhir library =====
// Gabungkan task Lentera + Classroom jadi satu daftar untuk di-upsert.
const lentera = $('S: Parse Lentera').first().json;
const courses = $('S: Pecah kelas').all().map((x) => x.json);
const works = $('S: Classroom tugas').all().map((x) => x.json);
const subs = $input.all().map((x) => x.json);
const warnings = [];
if (lentera.lentera_warning) warnings.push(lentera.lentera_warning);
const realCourses = courses.filter((c) => c.id);
if (realCourses.length === 0) {
  warnings.push(courses[0] && courses[0].classroom_error
    ? `Classroom gagal diambil: ${courses[0].classroom_error}`
    : 'Tidak ada kelas Classroom aktif yang relevan.');
}
const settings = $('S: Muat setting').first().json.settings || {};
const ignored = (courses[0] && courses[0].ignored) || [];
const classroom = realCourses.length
  ? classroomToTasks(courses, works, subs, { since: parseSemesterStart(settings.semester_start) })
  : [];
const now = new Date();
const all = filterRelevant([...(lentera.lentera_tasks || []), ...classroom], now);
return [{
  json: {
    tasks_json: JSON.stringify(all),
    // nama kelas yang dilewati: tugas lama dari kelas ini yang masih "open"
    // di database akan ditandai dropped oleh query sinkron.
    ignored_courses_json: JSON.stringify(ignored.map((c) => c.name)),
    kelas_dilewati: ignored,
    sources: { lentera: (lentera.lentera_tasks || []).length, classroom: classroom.length, dikirim: all.length },
    warnings,
  },
}];

// ===== library (dibangun dari src/lib — edit di sana, bukan di sini) =====
// ---------------------------------------------------------------------------
// lib/time.js — helper waktu. Indonesia tidak memakai DST, jadi zona waktu
// cukup dinyatakan sebagai offset tetap (WIB = +420 menit).
// ---------------------------------------------------------------------------

const MS_MIN = 60 * 1000;
const MS_DAY = 24 * 60 * MS_MIN;
const HARI = ['Min', 'Sen', 'Sel', 'Rab', 'Kam', 'Jum', 'Sab'];
const BULAN = ['Jan', 'Feb', 'Mar', 'Apr', 'Mei', 'Jun', 'Jul', 'Agu', 'Sep', 'Okt', 'Nov', 'Des'];

function pad2(n) {
  return String(n).padStart(2, '0');
}

/** Komponen tanggal/jam lokal dari sebuah Date (UTC) + offset menit. */
function localParts(date, offsetMin) {
  const d = new Date(date.getTime() + offsetMin * MS_MIN);
  return {
    y: d.getUTCFullYear(),
    m: d.getUTCMonth() + 1,
    d: d.getUTCDate(),
    hh: d.getUTCHours(),
    mm: d.getUTCMinutes(),
    dow: d.getUTCDay(),
  };
}

/** Date (UTC) dari tanggal + jam lokal. */
function localToDate(y, m, d, hh, mm, offsetMin) {
  return new Date(Date.UTC(y, m - 1, d, hh, mm) - offsetMin * MS_MIN);
}

/** Awal hari lokal (00:00) untuk tanggal tertentu, sebagai Date UTC. */
function startOfLocalDay(date, offsetMin) {
  const p = localParts(date, offsetMin);
  return localToDate(p.y, p.m, p.d, 0, 0, offsetMin);
}

/** "08:30" -> 510 menit. */
function parseHHMM(s, fallback) {
  const m = /^(\d{1,2}):(\d{2})$/.exec(String(s || '').trim());
  if (!m) return fallback;
  return Number(m[1]) * 60 + Number(m[2]);
}

/** Kunci tanggal lokal "2026-10-23". */
function localDateKey(date, offsetMin) {
  const p = localParts(date, offsetMin);
  return `${p.y}-${pad2(p.m)}-${pad2(p.d)}`;
}

/** ISO dengan offset lokal: "2026-10-23T09:00:00+07:00". */
function isoLocal(date, offsetMin) {
  const p = localParts(date, offsetMin);
  const sign = offsetMin >= 0 ? '+' : '-';
  const abs = Math.abs(offsetMin);
  return `${p.y}-${pad2(p.m)}-${pad2(p.d)}T${pad2(p.hh)}:${pad2(p.mm)}:00${sign}${pad2(Math.floor(abs / 60))}:${pad2(abs % 60)}`;
}

/** "Kam 23 Okt 09:00" */
function fmtLocal(date, offsetMin, withTime = true) {
  const p = localParts(date, offsetMin);
  const base = `${HARI[p.dow]} ${p.d} ${BULAN[p.m - 1]}`;
  return withTime ? `${base} ${pad2(p.hh)}:${pad2(p.mm)}` : base;
}

/** "09:00" */
function fmtClock(date, offsetMin) {
  const p = localParts(date, offsetMin);
  return `${pad2(p.hh)}:${pad2(p.mm)}`;
}

/** Bulatkan ke atas ke kelipatan `step` menit. */
function ceilToStep(date, stepMin) {
  const step = stepMin * MS_MIN;
  return new Date(Math.ceil(date.getTime() / step) * step);
}

// ---------------------------------------------------------------------------
// lib/scheduler.js — penjadwal deterministik Jarvis Akademik.
//
// Prinsip: LLM TIDAK menghitung jam. Agent hanya memutuskan prioritas
// (bobot, target %, hari tidak tersedia), lalu memanggil fungsi ini lewat
// tool `susun_ulang_jadwal`. Fungsi ini menjamin:
//   1. tidak ada blok yang bentrok dengan event lain / waktu tidak tersedia,
//   2. semua blok berada di jam belajar yang diizinkan,
//   3. blok sebuah tugas selesai sebelum deadline (dikurangi buffer),
//   4. beban harian dan beban per tugas per hari dibatasi.
// Algoritma: Earliest Deadline First (EDF) greedy, potong per blok.
// Butuh lib/time.js.
// ---------------------------------------------------------------------------

const SCHED_DEFAULTS = {
  study_start: '08:00',
  study_end: '22:00',
  max_daily_minutes: 300,
  max_task_minutes_per_day: 120,
  block_max_minutes: 90,
  block_min_minutes: 30,
  break_minutes: 15,
  horizon_days: 14,
  deadline_buffer_minutes: 120,
  tz_offset_minutes: 420,
  rest_days: '', // mis. "0" (Minggu) atau "0,6"
  busy_all_day: 'false',
};

function readConfig(settings) {
  const s = Object.assign({}, SCHED_DEFAULTS, settings || {});
  const num = (k) => {
    const n = Number(s[k]);
    return Number.isFinite(n) ? n : Number(SCHED_DEFAULTS[k]);
  };
  return {
    studyStart: parseHHMM(s.study_start, 8 * 60),
    studyEnd: parseHHMM(s.study_end, 22 * 60),
    maxDaily: num('max_daily_minutes'),
    maxTaskDay: num('max_task_minutes_per_day'),
    blockMax: num('block_max_minutes'),
    blockMin: num('block_min_minutes'),
    breakMin: num('break_minutes'),
    horizonDays: num('horizon_days'),
    bufferMin: num('deadline_buffer_minutes'),
    offset: num('tz_offset_minutes'),
    restDays: String(s.rest_days || '')
      .split(',')
      .map((x) => x.trim())
      .filter((x) => x !== '')
      .map(Number),
    busyAllDay: String(s.busy_all_day) === 'true',
  };
}

/**
 * Event Google Calendar (JSON API) -> interval sibuk.
 * Event all-day dan event "transparent" (Available) diabaikan kecuali diminta.
 */
function gcalEventsToBusy(events, cfg, label) {
  const out = [];
  for (const ev of events || []) {
    if (!ev || ev.status === 'cancelled' || !ev.start) continue;
    if (ev.transparency === 'transparent') continue;
    let s;
    let e;
    if (ev.start.dateTime) {
      s = new Date(ev.start.dateTime);
      e = new Date((ev.end && ev.end.dateTime) || ev.start.dateTime);
    } else if (ev.start.date) {
      if (!cfg.busyAllDay) continue;
      const [y, m, d] = ev.start.date.split('-').map(Number);
      s = localToDate(y, m, d, 0, 0, cfg.offset);
      const [y2, m2, d2] = ((ev.end && ev.end.date) || ev.start.date).split('-').map(Number);
      e = localToDate(y2, m2, d2, 0, 0, cfg.offset);
    } else {
      continue;
    }
    if (!(e > s)) continue; // event 0 menit (mis. deadline Lentera) bukan waktu sibuk
    out.push({ start: s, end: e, label: label || ev.summary || 'event' });
  }
  return out;
}

/** Gabungkan interval yang tumpang tindih. */
function mergeIntervals(list) {
  const sorted = (list || [])
    .filter((x) => x && x.end > x.start)
    .map((x) => ({ start: new Date(x.start), end: new Date(x.end) }))
    .sort((a, b) => a.start - b.start);
  const out = [];
  for (const cur of sorted) {
    const last = out[out.length - 1];
    if (last && cur.start <= last.end) {
      if (cur.end > last.end) last.end = cur.end;
    } else {
      out.push(cur);
    }
  }
  return out;
}

/** Slot kosong per hari di jam belajar, dikurangi waktu sibuk. */
function buildFreeSlots(now, busy, cfg) {
  const begin = ceilToStep(new Date(now.getTime() + 5 * MS_MIN), 15);
  const day0 = startOfLocalDay(now, cfg.offset);
  const merged = mergeIntervals(busy);
  const slots = [];
  for (let i = 0; i <= cfg.horizonDays; i++) {
    const dayStart = new Date(day0.getTime() + i * MS_DAY);
    const p = localParts(dayStart, cfg.offset);
    if (cfg.restDays.includes(p.dow)) continue;
    let ws = new Date(dayStart.getTime() + cfg.studyStart * MS_MIN);
    const we = new Date(dayStart.getTime() + cfg.studyEnd * MS_MIN);
    if (we <= begin) continue;
    if (ws < begin) ws = begin;
    let cursor = ws;
    const dayKey = localDateKey(dayStart, cfg.offset);
    for (const b of merged) {
      if (b.end <= cursor || b.start >= we) continue;
      if (b.start > cursor) slots.push({ s: cursor, e: new Date(Math.min(b.start, we)), dayKey });
      if (b.end > cursor) cursor = b.end;
      if (cursor >= we) break;
    }
    if (cursor < we) slots.push({ s: cursor, e: we, dayKey });
  }
  return slots.filter((x) => (x.e - x.s) / MS_MIN >= Math.min(cfg.blockMin, 15));
}

function remainingMinutes(t) {
  const target = Number.isFinite(Number(t.target_pct)) ? Number(t.target_pct) : 100;
  const effort = Number(t.effort_minutes) || 0;
  const done = Number(t.done_minutes) || 0;
  return Math.max(0, Math.round((effort * target) / 100) - done);
}

/**
 * Jadwalkan tugas.
 * @param {{now: Date, tasks: object[], busy: {start,end}[], settings: object}} input
 * @returns {{blocks, infeasible, overdue, perDay, stats, config}}
 */
function scheduleTasks({ now, tasks, busy, settings }) {
  const cfg = readConfig(settings);
  const slots = buildFreeSlots(now, busy, cfg);
  const horizonEnd = new Date(startOfLocalDay(now, cfg.offset).getTime() + (cfg.horizonDays + 1) * MS_DAY);
  const dayUsed = {};
  const blocks = [];
  const infeasible = [];
  const overdue = [];

  const queue = [];
  for (const t of tasks || []) {
    if (t.status && t.status !== 'open') continue;
    const need = remainingMinutes(t);
    if (need <= 0) continue;
    const deadline = t.deadline ? new Date(t.deadline) : null;
    if (deadline && deadline <= now) {
      overdue.push({ task_id: t.id, title: t.title, course: t.course, deadline: deadline.toISOString(), remaining_minutes: need });
      continue;
    }
    let due = deadline ? new Date(deadline.getTime() - cfg.bufferMin * MS_MIN) : horizonEnd;
    if (deadline && due <= now) due = deadline; // deadline mepet: buffer dilepas
    if (due > horizonEnd) due = horizonEnd;
    queue.push({ t, need, deadline, due });
  }

  queue.sort((a, b) => {
    const da = a.deadline ? a.deadline.getTime() : Infinity;
    const db = b.deadline ? b.deadline.getTime() : Infinity;
    if (da !== db) return da - db;
    const w = (Number(b.t.weight) || 0) - (Number(a.t.weight) || 0);
    if (w !== 0) return w;
    return (Number(a.t.id) || 0) - (Number(b.t.id) || 0);
  });

  for (const q of queue) {
    let remaining = q.need;
    const taskDay = {};
    // Pass 1: hormati batas per tugas per hari (agar belajar tersebar).
    // Pass 2: kalau masih kurang, batas itu dilepas (lebih baik padat daripada
    // tidak selesai). Batas total harian tetap berlaku di kedua pass.
    for (const perTaskCap of [cfg.maxTaskDay, Infinity]) {
      for (const slot of slots) {
        if (remaining <= 0 || slot.s >= q.due) break;
        // Satu slot bisa menampung beberapa blok berturut-turut.
        for (;;) {
          if (remaining <= 0 || slot.s >= q.due) break;
          const usable = (Math.min(slot.e, q.due) - slot.s) / MS_MIN;
          const dayLeft = cfg.maxDaily - (dayUsed[slot.dayKey] || 0);
          const taskLeft = perTaskCap - (taskDay[slot.dayKey] || 0);
          let chunk = Math.min(cfg.blockMax, remaining, usable, dayLeft, taskLeft);
          chunk = Math.floor(chunk / 5) * 5;
          if (chunk <= 0 || chunk < Math.min(cfg.blockMin, remaining)) break;
          const start = new Date(slot.s);
          const end = new Date(start.getTime() + chunk * MS_MIN);
          blocks.push({ task: q.t, start, end, minutes: chunk, dayKey: slot.dayKey, deadline: q.deadline });
          slot.s = new Date(end.getTime() + cfg.breakMin * MS_MIN);
          if (slot.s > slot.e) slot.s = new Date(slot.e);
          dayUsed[slot.dayKey] = (dayUsed[slot.dayKey] || 0) + chunk;
          taskDay[slot.dayKey] = (taskDay[slot.dayKey] || 0) + chunk;
          remaining -= chunk;
        }
      }
    }
    if (remaining > 0) {
      const scheduled = q.need - remaining;
      infeasible.push({
        task_id: q.t.id,
        title: q.t.title,
        course: q.t.course,
        weight: q.t.weight,
        deadline: q.deadline ? q.deadline.toISOString() : null,
        needed_minutes: q.need,
        scheduled_minutes: scheduled,
        feasible_pct: Math.round((scheduled / q.need) * 100),
      });
    }
  }

  blocks.sort((a, b) => a.start - b.start);
  const out = blocks.map((b) => {
    const t = b.task;
    const course = t.course ? `${t.course}: ` : '';
    const dl = b.deadline ? fmtLocal(b.deadline, cfg.offset) : 'tanpa deadline';
    return {
      task_id: t.id,
      title: t.title,
      course: t.course || '',
      start: b.start.toISOString(),
      end: b.end.toISOString(),
      start_local: isoLocal(b.start, cfg.offset),
      end_local: isoLocal(b.end, cfg.offset),
      minutes: b.minutes,
      day: b.dayKey,
      summary: `[Jarvis] ${course}${t.title}`,
      description:
        `Deadline: ${dl}\nSisa effort sebelum blok ini: ±${remainingMinutes(t)} menit\n\n` +
        'Dibuat otomatis oleh Jarvis Akademik. Jangan edit manual — ubah lewat Telegram.',
    };
  });

  const perDayMap = {};
  for (const b of out) {
    perDayMap[b.day] = perDayMap[b.day] || { day: b.day, minutes: 0, blocks: 0 };
    perDayMap[b.day].minutes += b.minutes;
    perDayMap[b.day].blocks += 1;
  }
  const perDay = Object.values(perDayMap).sort((a, b) => (a.day < b.day ? -1 : 1));
  const totalNeed = queue.reduce((s, q) => s + q.need, 0);
  const totalScheduled = out.reduce((s, b) => s + b.minutes, 0);
  const heavyDays = perDay.filter((d) => d.minutes >= cfg.maxDaily * 0.9).map((d) => d.day);

  return {
    blocks: out,
    infeasible,
    overdue,
    perDay,
    stats: { tasks_considered: queue.length, total_need_minutes: totalNeed, total_scheduled_minutes: totalScheduled, heavy_days: heavyDays },
    config: cfg,
  };
}
// ===== akhir library =====
// Inti replanning: kumpulkan waktu sibuk, jalankan penjadwal deterministik.
const data = $('R: Muat data').first().json;
const settings = data.settings || {};
if (!/@/.test(settings.jarvis_calendar_id || '') || /^xxxx@/.test(settings.jarvis_calendar_id)) {
  throw new Error('jarvis_calendar_id belum diisi di tabel settings.');
}
const cfg = readConfig(settings);
const now = new Date();

const mainEvents = $('R: Event kalender utama').all().map((x) => x.json).filter((e) => e && e.id);
const jarvisEvents = $input.all().map((x) => x.json).filter((e) => e && e.id);

// Waktu sibuk = acara kalender utama + periode tidak tersedia + blok Jarvis
// yang sedang berjalan (tidak dihapus).
const busy = gcalEventsToBusy(mainEvents, cfg);
for (const u of data.unavailable || []) {
  busy.push({ start: new Date(u.start), end: new Date(u.end), label: u.label });
}
const toDelete = [];
for (const e of jarvisEvents) {
  const s = new Date((e.start && (e.start.dateTime || e.start.date)) || 0);
  const en = new Date((e.end && (e.end.dateTime || e.end.date)) || 0);
  if (s >= now) toDelete.push(e.id);
  else if (en > now) busy.push({ start: s, end: en, label: 'blok Jarvis berjalan' });
}

const result = scheduleTasks({ now, tasks: data.tasks || [], busy, settings });
delete result.config;
return [{
  json: {
    ...result,
    now: now.toISOString(),
    to_delete: toDelete,
    busy_count: busy.length,
    jarvis_calendar_id: settings.jarvis_calendar_id,
  },
}];

// Pasangkan blok dengan event Google Calendar yang berhasil dibuat.
const blocks = $('R: Daftar blok baru').all().map((x) => x.json).filter((b) => b.start);
const created = $input.all().map((x) => x.json);
const rows = [];
let failed = 0;
blocks.forEach((b, i) => {
  const ev = created[i] || {};
  if (!ev.id) {
    failed += 1;
    return;
  }
  rows.push({ task_id: b.task_id, start_at: b.start, end_at: b.end, gcal_event_id: ev.id });
});
const deleted = $('R: Hapus blok lama').all().filter((x) => x.json && !x.json.error).length;
return [{ json: { rows_json: JSON.stringify(rows), created_count: rows.length, failed_count: failed, deleted_events: deleted } }];

