// ===== library (dibangun dari src/lib — edit di sana, bukan di sini) =====
// ---------------------------------------------------------------------------
// lib/time.js — helper waktu. Indonesia tidak memakai DST, jadi zona waktu
// cukup dinyatakan sebagai offset tetap (WIB = +420 menit).
// ---------------------------------------------------------------------------

const MS_MIN = 60 * 1000;
const MS_DAY = 24 * 60 * MS_MIN;
const HARI = ['Min', 'Sen', 'Sel', 'Rab', 'Kam', 'Jum', 'Sab'];
const BULAN = ['Jan', 'Feb', 'Mar', 'Apr', 'Mei', 'Jun', 'Jul', 'Agu', 'Sep', 'Okt', 'Nov', 'Des'];

function pad2(n) {
  return String(n).padStart(2, '0');
}

/** Komponen tanggal/jam lokal dari sebuah Date (UTC) + offset menit. */
function localParts(date, offsetMin) {
  const d = new Date(date.getTime() + offsetMin * MS_MIN);
  return {
    y: d.getUTCFullYear(),
    m: d.getUTCMonth() + 1,
    d: d.getUTCDate(),
    hh: d.getUTCHours(),
    mm: d.getUTCMinutes(),
    dow: d.getUTCDay(),
  };
}

/** Date (UTC) dari tanggal + jam lokal. */
function localToDate(y, m, d, hh, mm, offsetMin) {
  return new Date(Date.UTC(y, m - 1, d, hh, mm) - offsetMin * MS_MIN);
}

/** Awal hari lokal (00:00) untuk tanggal tertentu, sebagai Date UTC. */
function startOfLocalDay(date, offsetMin) {
  const p = localParts(date, offsetMin);
  return localToDate(p.y, p.m, p.d, 0, 0, offsetMin);
}

/** "08:30" -> 510 menit. */
function parseHHMM(s, fallback) {
  const m = /^(\d{1,2}):(\d{2})$/.exec(String(s || '').trim());
  if (!m) return fallback;
  return Number(m[1]) * 60 + Number(m[2]);
}

/** Kunci tanggal lokal "2026-10-23". */
function localDateKey(date, offsetMin) {
  const p = localParts(date, offsetMin);
  return `${p.y}-${pad2(p.m)}-${pad2(p.d)}`;
}

/** ISO dengan offset lokal: "2026-10-23T09:00:00+07:00". */
function isoLocal(date, offsetMin) {
  const p = localParts(date, offsetMin);
  const sign = offsetMin >= 0 ? '+' : '-';
  const abs = Math.abs(offsetMin);
  return `${p.y}-${pad2(p.m)}-${pad2(p.d)}T${pad2(p.hh)}:${pad2(p.mm)}:00${sign}${pad2(Math.floor(abs / 60))}:${pad2(abs % 60)}`;
}

/** "Kam 23 Okt 09:00" */
function fmtLocal(date, offsetMin, withTime = true) {
  const p = localParts(date, offsetMin);
  const base = `${HARI[p.dow]} ${p.d} ${BULAN[p.m - 1]}`;
  return withTime ? `${base} ${pad2(p.hh)}:${pad2(p.mm)}` : base;
}

/** "09:00" */
function fmtClock(date, offsetMin) {
  const p = localParts(date, offsetMin);
  return `${pad2(p.hh)}:${pad2(p.mm)}`;
}

/** Bulatkan ke atas ke kelipatan `step` menit. */
function ceilToStep(date, stepMin) {
  const step = stepMin * MS_MIN;
  return new Date(Math.ceil(date.getTime() / step) * step);
}
// ===== akhir library =====
// Ringkasan hasil susun ulang untuk agent (dan pesan pagi).
const res = $('R: Penjadwal').first().json;
const col = $('R: Kumpulkan event').first().json;
const data = $('R: Muat data').first().json;
const off = Number((data.settings || {}).tz_offset_minutes || 420);
const now = new Date();
const todayKey = localDateKey(now, off);
const tomorrowKey = localDateKey(new Date(now.getTime() + MS_DAY), off);
const keyToDate = (k) => {
  const [y, m, d] = k.split('-').map(Number);
  return localToDate(y, m, d, 12, 0, off);
};
const line = (b) => `${fmtClock(new Date(b.start), off)}-${fmtClock(new Date(b.end), off)} ${b.course ? `${b.course}: ` : ''}${b.title}`;
const fmtDl = (iso) => (iso ? fmtLocal(new Date(iso), off) : 'tanpa deadline');

let sync = null;
if ($('S: Simpan tugas').isExecuted) {
  const s = $('S: Simpan tugas').first().json;
  const n = $('S: Gabung & normalisasi').first().json;
  sync = {
    tugas_baru: s.new_tasks || [],
    diperbarui: Number(s.updated_count || 0),
    ditandai_selesai_dari_classroom: Number(s.marked_done_count || 0),
    kuis_lentera_kedaluwarsa: Number(s.expired_count || 0),
    tugas_kelas_lama_dibuang: Number(s.dropped_from_old_courses_count || 0),
    kelas_dilewati: (n.kelas_dilewati || []).map((c) => c.name),
    sumber: n.sources,
    peringatan: n.warnings,
  };
}

const summary = {
  ok: col.failed_count === 0,
  blok_dibuat: col.created_count,
  blok_gagal_dibuat: col.failed_count,
  total_menit_terjadwal: res.stats.total_scheduled_minutes,
  total_menit_dibutuhkan: res.stats.total_need_minutes,
  blok_hari_ini: res.blocks.filter((b) => b.day === todayKey).map(line),
  blok_besok: res.blocks.filter((b) => b.day === tomorrowKey).map(line),
  beban_per_hari: res.perDay.map((d) => ({ hari: fmtLocal(keyToDate(d.day), off, false), menit: d.minutes, blok: d.blocks })),
  hari_padat: res.stats.heavy_days.map((k) => fmtLocal(keyToDate(k), off, false)),
  tidak_muat: res.infeasible.map((x) => ({
    task_id: x.task_id,
    tugas: x.course ? `${x.course}: ${x.title}` : x.title,
    bobot: x.weight,
    deadline: fmtDl(x.deadline),
    butuh_menit: x.needed_minutes,
    terjadwal_menit: x.scheduled_minutes,
    realistis_persen: x.feasible_pct,
  })),
  lewat_deadline: res.overdue.map((x) => ({
    task_id: x.task_id,
    tugas: x.course ? `${x.course}: ${x.title}` : x.title,
    deadline: fmtDl(x.deadline),
    sisa_menit: x.remaining_minutes,
  })),
  sinkronisasi: sync,
  telegram_chat_id: (data.settings || {}).telegram_chat_id || '',
};
return [{ json: summary }];

// Pesan pagi setelah sinkronisasi + susun ulang.
const s = $input.first().json;
if (!s.telegram_chat_id) throw new Error('telegram_chat_id kosong: kirim /start ke bot dulu.');
const L = ['☀️ Selamat pagi! Ini rencana belajarmu.'];
const sync = s.sinkronisasi;
if (sync && sync.tugas_baru.length) {
  L.push('', `📥 Tugas baru (${sync.tugas_baru.length}):`);
  for (const t of sync.tugas_baru.slice(0, 8)) L.push(`• ${t.course ? `${t.course}: ` : ''}${t.title} — ${t.deadline_wib || 'tanpa deadline'}`);
}
L.push('', s.blok_hari_ini.length ? '📅 Hari ini:' : '📅 Hari ini tidak ada blok belajar.');
for (const b of s.blok_hari_ini) L.push(`• ${b}`);
if (s.tidak_muat.length) {
  L.push('', '⚠️ Tidak cukup waktu:');
  for (const x of s.tidak_muat.slice(0, 5)) L.push(`• ${x.tugas} — realistis ${x.realistis_persen}% sebelum ${x.deadline}`);
  L.push('Balas pesan ini kalau mau aku atur prioritasnya.');
}
if (s.hari_padat.length) L.push('', `🔥 Hari padat: ${s.hari_padat.join(', ')}`);
if (s.lewat_deadline.length) L.push('', `⏰ ${s.lewat_deadline.length} tugas sudah lewat deadline. Sudah dikumpulkan? Kabari ya.`);
if (sync && sync.peringatan && sync.peringatan.length) L.push('', `ℹ️ ${sync.peringatan.join(' | ')}`);
const escHtml = (t) => String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const plain = L.join('\n');
return [{ json: { chat_id: s.telegram_chat_id, text: escHtml(plain), plain } }];

// Pesan check-in malam. Disimpan juga ke memori agent agar balasan user
// ("udah", "belum, capek") langsung dipahami konteksnya.
const d = $input.first().json;
if (!d.chat_id) throw new Error('telegram_chat_id kosong: kirim /start ke bot dulu.');
const L = ['🌙 Check-in malam'];
if (d.today_blocks.length) {
  L.push('', 'Rencana belajar hari ini:');
  for (const b of d.today_blocks) L.push(`• ${b.jam} ${b.course ? `${b.course}: ` : ''}${b.title} [#${b.task_id}]`);
  L.push('', 'Mana yang sudah dikerjakan? Jawab bebas aja, misal "Statistik udah, Jarkom baru setengah" atau "belum, capek".');
} else {
  L.push('', 'Hari ini tidak ada blok belajar terjadwal.');
}
if (d.due_soon.length) {
  L.push('', '⏳ Deadline 3 hari ke depan:');
  for (const t of d.due_soon.slice(0, 6)) L.push(`• ${t.course ? `${t.course}: ` : ''}${t.title} — ${t.deadline_wib}`);
}
if (d.tomorrow_blocks.length) {
  L.push('', 'Besok:');
  for (const b of d.tomorrow_blocks.slice(0, 6)) L.push(`• ${b.jam} ${b.course ? `${b.course}: ` : ''}${b.title}`);
}
const escHtml = (t) => String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const plain = L.join('\n');
return [{ json: { chat_id: String(d.chat_id), text: escHtml(plain), plain } }];
